 select id,'الأرصاد الجوية التطبيقية وأجهزة الرصد','مبادئ الرصد الجوي وأجهزة القياس والمحطات الآلية وضمان جودة البيانات والمعايرة.',10,false from c
 on conflict(course_id,title) do update set description=excluded.description returning id,course_id
),
u1 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'أساسيات الرصد ومحطات الأرصاد','مبادئ الرصد وتصنيف المحطات واختيار المواقع.',1,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u2 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'أجهزة قياس العناصر الجوية','أجهزة الحرارة والرطوبة والضغط.',2,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u3 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'أجهزة الرياح والهطول والإشعاع','أجهزة قياس الرياح والهطول والإشعاع الشمسي.',3,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u4 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'تشغيل محطات الرصد الآلية','الحساسات ووحدات التسجيل والطاقة والاتصالات.',4,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u5 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'جودة القياسات والمعايرة','مراقبة جودة البيانات والتحقق والمعايرة.',5,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values
('meteorological-observation-principles-and-station-types','مبادئ الرصد الجوي وأنواع محطات الأرصاد','مبادئ القياس والرصد الجوي وتصنيف المحطات ومواقعها وتمثيلها المكاني والزمني.','{"blocks":[{"type":"heading","text":"ما الرصد الجوي؟"},{"type":"text","text":"الرصد الجوي هو القياس المنظم لعناصر الغلاف الجوي وتوثيقها وفق إجراءات ومعايير محددة. يوفر الرصد بيانات آنية للتنبؤ والتحذير، وسجلات طويلة الأمد لدراسة المناخ والتحقق من النماذج."},{"type":"heading","text":"أهداف شبكة الرصد"},{"type":"list","items":["متابعة الحالة الجوية وتحليل تطورها.","توفير بيانات أولية للنماذج العددية.","إصدار التحذيرات ومتابعة الظواهر الخطرة.","بناء سجلات مناخية طويلة الأمد.","دعم الطيران والزراعة والمياه والنقل والبحث العلمي."]},{"type":"heading","text":"أنواع المحطات بحسب الوظيفة"},{"type":"list","items":["محطات سينوبتيكية للرصد المتزامن وتحليل الحالة الجوية.","محطات مناخية لتسجيل العناصر على مدد طويلة.","محطات مطارية لدعم سلامة الطيران.","محطات زراعية لمراقبة المناخ الدقيق والتربة والتبخر.","محطات بحرية وجبلية ومحطات خاصة للبحث والإنذار."]},{"type":"heading","text":"المحطات اليدوية والآلية"},{"type":"text","text":"تعتمد المحطات اليدوية على مراقب وأجهزة تقليدية وإجراءات قراءة وتدوين. أما المحطات الآلية فتستخدم حساسات ووحدات تسجيل واتصال لإرسال القياسات تلقائياً. وقد تجمع الشبكات الحديثة بين النوعين للتحقق والاستمرارية."},{"type":"heading","text":"اختيار موقع المحطة"},{"type":"text","text":"ينبغي أن يمثل الموقع البيئة المراد رصدها، وأن يكون بعيداً قدر الإمكان عن مصادر الحرارة والعوائق والاضطرابات المحلية غير الممثلة. توثق الإحداثيات والارتفاع ووصف السطح والعوائق والتغيرات المحيطة بالموقع."},{"type":"heading","text":"تمثيل القياس"},{"type":"text","text":"لا تمثل قراءة المحطة بالضرورة كل المنطقة المحيطة بها؛ فالارتفاع والتضاريس والساحل والغطاء الأرضي قد تسبب فروقاً محلية. لذلك توزع المحطات وفق أهداف الشبكة والتباين المكاني ومناطق الحاجة."},{"type":"heading","text":"أوقات الرصد والتزامن"},{"type":"text","text":"تحدد جداول الرصد بحسب غرض المحطة والمعايير المعتمدة. يجب توثيق المنطقة الزمنية والتوقيت العالمي UTC وأوقات أخذ العينات والتجميع والإرسال، لأن اختلاف التوقيت يسبب أخطاء في المقارنة والتحليل."},{"type":"heading","text":"الميتاداتا وسجل المحطة"},{"type":"list","items":["رمز المحطة واسمها وموقعها وإحداثياتها.","الارتفاع ونوع السطح والبيئة المحيطة.","الأجهزة والحساسات ومجالات القياس ودقتها.","تواريخ التركيب والاستبدال والمعايرة والصيانة.","تاريخ نقل المحطة أو تغيير ظروف الموقع."]},{"type":"heading","text":"السلامة واستمرارية التشغيل"},{"type":"text","text":"يتطلب التشغيل الآمن حماية العاملين والمعدات من الكهرباء والطقس القاسي والارتفاعات، مع إجراءات صيانة موثقة وخطة للتعامل مع انقطاع الطاقة أو الاتصالات وفقد البيانات."},{"type":"callout","text":"قيمة الرصد لا تعتمد على دقة الحساس وحدها؛ فالموقع والتمثيل والصيانة والتوقيت والبيانات الوصفية عناصر أساسية أيضاً."},{"type":"example","text":"مثال: قبل اعتماد محطة جديدة ضمن شبكة مناخية، راجع تمثيل الموقع وتاريخ استخدام الأرض حوله، وقارن قراءاته بمحطات مجاورة، ووثق الأجهزة والتوقيت والارتفاع."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"شبكة الرصد الجيدة تجمع بين أجهزة مناسبة ومواقع ممثلة وإجراءات موحدة وبيانات وصفية دقيقة واستمرارية تشغيل موثوقة."}]}',400,45,'["شرح أهداف الرصد الجوي ومبادئ القياس","تمييز أنواع محطات الأرصاد بحسب الوظيفة والتشغيل","تحديد متطلبات اختيار موقع محطة رصد"]','أساسيات الرصد ومحطات الأرصاد'),
('temperature-humidity-and-pressure-instruments','أجهزة قياس درجة الحرارة والرطوبة والضغط','التعرف إلى حساسات الحرارة والرطوبة والبارومترات ومبادئ التركيب والقراءة ومصادر الخطأ.','{"blocks":[{"type":"heading","text":"قياس درجة حرارة الهواء"},{"type":"text","text":"تقاس درجة حرارة الهواء بحساسات تتأثر بالتبادل الحراري مع الهواء والإشعاع والسطوح المحيطة. لذلك يوضع الحساس في مأوى مناسب جيد التهوية يقلل تأثير الإشعاع المباشر والمطر والتسخين غير المرغوب."},{"type":"heading","text":"أنواع حساسات الحرارة"},{"type":"list","items":["مقاييس سائلة تقليدية تعتمد تغير حجم السائل.","مقاومات حرارية RTD يتغير مقدار مقاومتها مع الحرارة.","ثرمستورات ذات استجابة حساسة ضمن مجال محدد.","مزدوجات حرارية تعتمد فرق الجهد بين معدنين.","حساسات رقمية مدمجة في محطات الرصد الآلية."]},{"type":"heading","text":"مأوى أجهزة الحرارة"},{"type":"text","text":"يهدف المأوى الإشعاعي إلى تقليل التسخين المباشر مع السماح بمرور الهواء. يؤثر لون المأوى وتهويته وارتفاعه عن الأرض والسطح المحيط في جودة القياس، ويجب اتباع مواصفات الشبكة المعتمدة."},{"type":"heading","text":"قياس الرطوبة"},{"type":"text","text":"تعبر الرطوبة عن كمية بخار الماء في الهواء. من المقادير الشائعة الرطوبة النسبية وضغط بخار الماء ودرجة الندى. الرطوبة النسبية نسبة بين ضغط البخار الفعلي وضغط الإشباع عند درجة الحرارة نفسها."},{"type":"heading","text":"حساسات الرطوبة"},{"type":"list","items":["حساسات سعوية تتغير خصائصها الكهربائية مع امتصاص الرطوبة.","حساسات مقاومية تتغير مقاومتها مع الرطوبة.","أجهزة قياس رطوبة مرجعية أو نفسية تستخدم للتحقق في بعض التطبيقات.","أجهزة قياس نقطة الندى في التطبيقات المتخصصة."]},{"type":"heading","text":"تأثير الحرارة على الرطوبة النسبية"},{"type":"text","text":"قد تتغير الرطوبة النسبية عند تغير درجة الحرارة حتى لو بقيت كمية بخار الماء ثابتة، لأن ضغط الإشباع يعتمد بقوة على الحرارة. لذلك ينبغي تفسير الرطوبة النسبية مع درجة الحرارة أو نقطة الندى."},{"type":"heading","text":"قياس الضغط الجوي"},{"type":"text","text":"يقاس الضغط الجوي باستخدام بارومترات إلكترونية أو تقليدية. تعتمد الحساسات الإلكترونية غالباً على تغير خصائص عنصر حساس للضغط، ثم تحول الإشارة إلى قيمة رقمية بعد المعايرة والتعويض الحراري."},{"type":"heading","text":"أنواع البارومترات"},{"type":"list","items":["البارومتر الزئبقي مرجع تاريخي يتطلب ضوابط سلامة خاصة.","البارومتر اللاسائلي يعتمد تشوه حجرة مرنة.","حساسات الضغط الإلكترونية تستخدم في المحطات الآلية.","قد تعرض المحطات ضغط المحطة أو ضغطاً مصححاً إلى مستوى سطح البحر."]},{"type":"heading","text":"ضغط المحطة وضغط سطح البحر"},{"type":"text","text":"ضغط المحطة هو الضغط المقاس عند ارتفاع المحطة. أما ضغط مستوى سطح البحر فهو قيمة محسوبة لتسهيل المقارنة الأفقية، وتعتمد على درجة الحرارة وطريقة الاختزال والارتفاع؛ لذلك يجب معرفة نوع الحقل قبل استخدامه في التحليل."},{"type":"heading","text":"التركيب والتحقق"},{"type":"list","items":["تحقق من مجال الحساس ودقته وزمن استجابته.","تجنب مصادر الحرارة والاهتزاز والتداخل الكهربائي.","قارن القياس بجهاز مرجعي أو محطة موثوقة.","راجع الانجراف والقفزات والقيم الثابتة غير الطبيعية.","سجل المعايرة والاستبدال وأي تعديل برمجي."]},{"type":"callout","text":"لا تخلط بين ضغط المحطة وضغط سطح البحر؛ استخدام الحقل غير المناسب قد ينتج تحليلاً خاطئاً لمراكز الضغط."},{"type":"example","text":"مثال: إذا سجلت محطة ساحلية ضغطاً أقل من محطة جبلية، فلا تستنتج وجود منخفض بينهما قبل توحيد نوع الضغط والتحقق من تصحيح الارتفاع والتوقيت."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تعتمد جودة قياسات الحرارة والرطوبة والضغط على مبدأ الحساس وموقعه وتركيبه ومعايرته، وعلى توثيق نوع المتغير والوحدة والارتفاع."}]}',410,50,'["شرح مبادئ عمل أجهزة الحرارة والرطوبة والضغط","تمييز أنواع الحساسات وأماكن تركيبها","تحديد مصادر الخطأ وإجراءات التحقق الأساسية"]','أجهزة قياس العناصر الجوية'),
('wind-precipitation-and-solar-radiation-instruments','أجهزة قياس الرياح والهطول والإشعاع الشمسي','مبادئ قياس سرعة الرياح واتجاهها والهطول والإشعاع وأهم القيود التشغيلية.','{"blocks":[{"type":"heading","text":"قياس سرعة الرياح"},{"type":"text","text":"تقاس سرعة الرياح بأجهزة تحول حركة الهواء إلى إشارة قابلة للقياس. من أشهرها مقياس الكؤوس ومقياس المروحة والمقاييس فوق الصوتية. تختلف الأجهزة في زمن الاستجابة والصيانة والقدرة على قياس السرعات المنخفضة والعالية."},{"type":"heading","text":"قياس اتجاه الرياح"},{"type":"text","text":"يستخدم دوار الرياح أو حساس اتجاه إلكتروني لتحديد الجهة التي تأتي منها الرياح، ويجب توثيق اصطلاح الاتجاه المستخدم والمرجع الشمالي وطريقة التعامل مع فترات السكون."},{"type":"heading","text":"تركيب أجهزة الرياح"},{"type":"text","text":"تؤثر العوائق والتضاريس والمباني في تدفق الهواء. يراعى ارتفاع التركيب وموقع الجهاز وانكشافه وفق معيار الرصد والغرض من القياس، مع تسجيل أي تغير في البيئة المحيطة."},{"type":"heading","text":"متوسط الرياح والهبات"},{"type":"text","text":"قد تسجل المحطة متوسطاً خلال نافذة زمنية وهبات قصيرة المدة. لا تقارن القيم قبل معرفة مدة المتوسط وتعريف الهبة وفترة أخذ العينات ووحدة القياس."},{"type":"heading","text":"قياس الهطول"},{"type":"text","text":"يقيس مقياس المطر كمية الهطول المتجمعة خلال فترة زمنية. تستخدم مقاييس تقليدية مدرجة أو مقاييس آلية مثل الدلو القلاب أو الوزن أو أجهزة بصرية، ولكل نوع حدود تتعلق بالرياح وشدة المطر والصيانة."},{"type":"heading","text":"الدلو القلاب"},{"type":"text","text":"يعتمد مقياس الدلو القلاب على انقلاب حجرتين صغيرتين بالتناوب عند امتلاء إحداهما بكمية محددة. يوفر قياسات آلية متتابعة، لكن قد تقل دقته في الهطول الشديد أو عند انسداد القمع أو عدم استواء الجهاز."},{"type":"heading","text":"الثلوج والهطول الصلب"},{"type":"text","text":"تحتاج الثلوج إلى أدوات وإجراءات مناسبة لقياس عمقها أو مكافئها المائي. لا يعادل عمق الثلج كمية الماء؛ فالكثافة تختلف باختلاف الحرارة والرياح ونوع البلورات والانضغاط."},{"type":"heading","text":"مصادر خطأ قياس المطر"},{"type":"list","items":["تأثير الرياح حول فتحة المقياس.","انسداد القمع أو تسرب الماء.","عدم استواء الجهاز أو خطأ مساحة الفتحة.","التبخر أو تأخر التسجيل.","فقدان البيانات أثناء الانقطاع أو الصيانة."]},{"type":"heading","text":"قياس الإشعاع الشمسي"},{"type":"text","text":"يقيس البيرانومتر الإشعاع الشمسي الكلي قصير الموجة على سطح أفقي، بينما يقيس البيرهيليومتر الإشعاع المباشر باستخدام تتبع قرص الشمس. ويمكن استخدام مقاييس أخرى لقياس الإشعاع المنعكس أو طويل الموجة."},{"type":"heading","text":"تركيب وصيانة أجهزة الإشعاع"},{"type":"text","text":"يتطلب القياس سطحاً مكشوفاً ومستوى أفقياً ونظافة القبة أو الحساس والتحقق من عدم وجود ظلال. تؤثر الترسبات والغبار والرطوبة والانجراف في القياس، ولذلك تسجل أعمال التنظيف والمعايرة."},{"type":"callout","text":"عند مقارنة بيانات المطر والرياح والإشعاع، تحقق من فترة التجميع والتوقيت والوحدة ونوع الحساس قبل تفسير الفروق."},{"type":"example","text":"مثال: قد تسجل محطة مطراً أقل من محطة قريبة بسبب اختلاف التعرض للرياح أو انسداد القمع. راجع سجل الصيانة والقراءات اللحظية ومقاييس مجاورة قبل اعتماد القيمة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"لكل عنصر جوي أجهزة وقيود قياس خاصة. التركيب الصحيح والصيانة والتوثيق الزمني ضرورية لتحويل الإشارة الحسية إلى سجل رصد موثوق."}]}',420,50,'["تمييز أجهزة قياس سرعة الرياح واتجاهها","شرح مقاييس الهطول وطرق تجميعه","التعرف إلى أجهزة قياس الإشعاع الشمسي"]','أجهزة الرياح والهطول والإشعاع'),
('automatic-weather-stations-and-data-loggers','محطات الرصد الآلية وأنظمة تسجيل البيانات','بنية المحطة الآلية والحساسات ووحدة التسجيل والطاقة والاتصالات وتدفق البيانات.','{"blocks":[{"type":"heading","text":"بنية محطة الرصد الآلية"},{"type":"text","text":"تتكون محطة الرصد الآلية عادة من حساسات، ووحدة جمع بيانات، وذاكرة محلية، ومصدر طاقة، ووسيلة اتصال، وهيكل تثبيت وحماية. تتكامل هذه المكونات لإنتاج قياسات مؤرخة قابلة للنقل والمعالجة."},{"type":"heading","text":"الحساسات وقنوات الإدخال"},{"type":"text","text":"تحول الحساسات المتغيرات الجوية إلى إشارات كهربائية أو رقمية. قد تكون القنوات تناظرية أو رقمية، ويجب ضبط نوع الإدخال والمجال ومعامل التحويل والوحدة بما يطابق مواصفات الحساس."},{"type":"heading","text":"وحدة جمع البيانات"},{"type":"text","text":"تقرأ وحدة التسجيل إشارات الحساسات وفق جدول زمني، وتطبق التحويلات أو الفحوص الأولية، ثم تحفظ القياسات مع الطابع الزمني ومعرف المحطة والحساس. يجب توثيق إعدادات أخذ العينات والتجميع."},{"type":"heading","text":"أخذ العينات والتجميع"},{"type":"text","text":"قد تؤخذ عينات سريعة ثم تحسب متوسطات أو قيم قصوى أو دنيا خلال فترة محددة. يجب الاحتفاظ بتعريف الإحصاء ونافذته الزمنية، لأن المتوسطات المختلفة لا تكون قابلة للمقارنة تلقائياً."},{"type":"heading","text":"الطوابع الزمنية"},{"type":"text","text":"ينبغي مزامنة ساعة المحطة وتحديد المنطقة الزمنية والتعامل مع التوقيت الصيفي عند الحاجة. التخزين بصيغة UTC مع الاحتفاظ بمرجع التوقيت يسهل دمج بيانات المحطات وتحليلها."},{"type":"heading","text":"التخزين المحلي والنسخ الاحتياطي"},{"type":"text","text":"تساعد الذاكرة المحلية على استمرار التسجيل عند انقطاع الاتصال. يجب تحديد سعة التخزين وسياسة الاحتفاظ وآلية استعادة السجلات بعد عودة الاتصال، مع منع تكرار السجلات أثناء إعادة الإرسال."},{"type":"heading","text":"مصادر الطاقة"},{"type":"list","items":["الشبكة الكهربائية مع حماية مناسبة.","الألواح الشمسية ومنظم الشحن.","البطاريات مع مراقبة الجهد والسعة.","إدارة استهلاك الاتصال والحساسات خلال فترات ضعف الطاقة."]},{"type":"heading","text":"الاتصالات ونقل البيانات"},{"type":"list","items":["شبكات خلوية أو لاسلكية أو أقمار صناعية حسب الموقع.","بروتوكولات نقل موثقة وآمنة.","إعادة المحاولة عند فشل الإرسال دون فقد السجل الأصلي.","مراقبة زمن آخر اتصال وحجم البيانات والفجوات."]},{"type":"heading","text":"تنسيقات البيانات"},{"type":"text","text":"يجب أن يحتوي السجل على معرف المحطة ووقت الرصد والمتغير والقيمة والوحدة وحالة الجودة ومصدر القياس. يمكن تبادل البيانات بصيغ CSV أو JSON أو صيغ معيارية متخصصة، مع قاموس واضح لأسماء الحقول."},{"type":"heading","text":"المراقبة والصيانة"},{"type":"text","text":"تراقب حالة البطارية والاتصال والذاكرة والحساسات، وتكشف القيم الثابتة أو الانقطاعات أو الانجراف. ينبغي أن تسجل التنبيهات وأعمال الصيانة ضمن سجل زمني قابل للتدقيق."},{"type":"callout","text":"نجاح إرسال البيانات لا يعني صحتها علمياً؛ يجب الفصل بين حالة الاتصال وحالة جودة القياس."},{"type":"example","text":"مثال: عند انقطاع اتصال محطة لمدة ساعتين، ينبغي أن تواصل وحدة التسجيل حفظ القراءات محلياً، ثم ترسل السجلات المتأخرة مع أوقاتها الأصلية ومعرفات تمنع إدخالها مرتين."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تعتمد المحطة الآلية على تكامل الحساسات والتسجيل والطاقة والاتصالات والبيانات الوصفية. التصميم الجيد يحافظ على السجل حتى عند تعطل أحد مكونات الاتصال."}]}',430,50,'["رسم مكونات محطة الرصد الآلية ووظيفة كل مكون","شرح أخذ العينات والتجميع والتخزين والاتصال","تحديد متطلبات الطاقة والاتصال واستمرارية البيانات"]','تشغيل محطات الرصد الآلية'),
('meteorological-data-quality-control-and-calibration','مراقبة جودة البيانات ومعايرة أجهزة الأرصاد','إجراءات مراقبة الجودة الآلية واليدوية وفحوص الاتساق والمقارنة والمعايرة والتوثيق.','{"blocks":[{"type":"heading","text":"لماذا مراقبة الجودة؟"},{"type":"text","text":"تهدف مراقبة الجودة إلى اكتشاف الأخطاء المحتملة قبل استخدام البيانات في التحليل أو التنبؤ أو الأرشفة المناخية. لا يعني اجتياز الفحص أن القيمة صحيحة قطعاً؛ بل يعني أنها لم تخالف الاختبارات المحددة."},{"type":"heading","text":"مراحل مراقبة الجودة"},{"type":"list","items":["فحص اكتمال السجل والحقول والوحدات والطابع الزمني.","فحوص الحدود الفيزيائية والقيم المسموح بها.","فحوص التغير الزمني والقيم الثابتة والانقطاعات.","فحوص الاتساق بين العناصر الجوية.","المقارنة المكانية مع محطات أو مصادر مستقلة.","المراجعة البشرية وتوثيق القرار النهائي."]},{"type":"heading","text":"فحص الحدود"},{"type":"text","text":"يقارن فحص الحدود القيم بنطاقات فيزيائية أو تشغيلية معقولة للمتغير والموقع والموسم. يجب أن تكون الحدود مرنة بما يكفي لعدم حذف الظواهر النادرة الحقيقية، وأن توثق النسخة المستخدمة."},{"type":"heading","text":"فحص التغير الزمني"},{"type":"text","text":"يكشف الفحص الزمني القفزات غير المعتادة أو ثبات القراءة لفترات طويلة أو معدلات تغير غير معقولة. ينبغي مراعاة أن بعض التغيرات السريعة حقيقية أثناء مرور الجبهات أو العواصف."},{"type":"heading","text":"فحص الاتساق بين المتغيرات"},{"type":"text","text":"تستخدم العلاقات الفيزيائية للكشف عن التناقضات، مثل اتساق درجة الندى مع حرارة الهواء والرطوبة، أو اتجاه الرياح مع السرعة، أو الهطول مع حالة الحساس. هذه الفحوص مؤشرات مراجعة وليست قواعد حذف آلية مطلقة."},{"type":"heading","text":"الفحص المكاني"},{"type":"text","text":"تقارن القراءة بمحطات قريبة أو تحليل شبكي أو رصد مستقل بعد مراعاة الارتفاع والتضاريس والبعد والاختلاف المحلي. اختلاف المحطة عن جيرانها قد يشير إلى خطأ أو إلى ظاهرة محلية حقيقية."},{"type":"heading","text":"أعلام الجودة"},{"type":"list","items":["صالح: اجتاز الفحوص المحددة.","مشتبه به: يحتاج مراجعة إضافية.","مفقود: لا توجد قراءة موثوقة للفترة.","معدل أو مصحح: تغيرت القيمة وفق إجراء موثق.","مرفوض: ثبت عدم صلاحية القيمة للاستخدام المحدد."]},{"type":"heading","text":"المعايرة والتحقق"},{"type":"text","text":"المعايرة تحدد العلاقة بين قراءة الجهاز ومرجع قياسي معلوم ضمن شروط محددة. أما التحقق فيقيّم ما إذا كان الجهاز يفي بمتطلبات الاستخدام. يجب تسجيل المرجع والنتائج وعدم اليقين وشروط المعايرة."},{"type":"heading","text":"التتبع المترولوجي"},{"type":"text","text":"يعني التتبع المترولوجي ربط نتيجة القياس بسلسلة موثقة من المعايرات إلى مراجع معترف بها، مع بيان عدم اليقين في كل مرحلة. لا يكفي وجود شهادة معايرة دون معرفة مجالها وتاريخها وشروطها."},{"type":"heading","text":"التصحيح والاستبدال"},{"type":"text","text":"إذا صححت قيمة أو استبدلت قراءة، احتفظ بالقيمة الأصلية وسجل القيمة المعالجة والسبب والطريقة والوقت والجهة المسؤولة. لا تستبدل البيانات الأصلية بصمت، خصوصاً في السجلات المناخية طويلة الأمد."},{"type":"heading","text":"مؤشرات أداء الشبكة"},{"type":"list","items":["نسبة اكتمال البيانات لكل محطة ومتغير.","معدل الانقطاعات وتأخر وصول السجلات.","نسبة القيم المشتبه بها والمرفوضة.","زمن معالجة التنبيهات وإغلاق الأعطال.","نسبة الأجهزة التي تمت معايرتها ضمن الجدول."]},{"type":"callout","text":"يجب ألا تتحول اختبارات الجودة إلى مرشح يحذف القيم المتطرفة الحقيقية؛ راجع السياق الجوي والمصادر المستقلة قبل الرفض."},{"type":"example","text":"مثال: سجلت محطة ارتفاعاً سريعاً في سرعة الرياح أثناء مرور جبهة. افحص بيانات الهبات والضغط والاتجاه ومحطات الجوار وسجل الجهاز؛ لا ترفض القيمة لمجرد أنها أعلى من المعتاد."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"مراقبة الجودة سلسلة فحوص آلية وبشرية ومعايرة موثقة. الحفاظ على القيمة الأصلية وسجل التعديلات أساس الثقة في بيانات الأرصاد."}]}',440,55,'["تطبيق مفاهيم مراقبة جودة البيانات الجوية","تمييز فحوص الحدود والاتساق والاستمرارية والمقارنة المكانية","شرح المعايرة والتتبع المترولوجي وتوثيق النتائج"]','جودة القياسات والمعايرة')
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,
case d.unit when 'أساسيات الرصد ومحطات الأرصاد' then u1.id when 'أجهزة قياس العناصر الجوية' then u2.id when 'أجهزة الرياح والهطول والإشعاع' then u3.id when 'تشغيل محطات الرصد الآلية' then u4.id else u5.id end,
d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الأرصاد الجوية التطبيقية وأجهزة الرصد',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;